const projectModal = document.getElementById("projectModal");
const projectModalTitle = document.getElementById("projectModalTitle");
const projectModalText = document.getElementById("projectModalText");
const projectModalStatus = document.getElementById("projectModalStatus");
const projectModalLink = document.getElementById("projectModalLink");
const projectMediaGallery = document.getElementById("projectMediaGallery");
const projectMediaGrid = document.getElementById("projectMediaGrid");

// Future project screenshots/videos can be added here without changing the modal layout.
// Example: projectMedia.vpn = [{ type: "image", src: "assets/projects/vpn-01.jpg", alt: "VV.CEO VPN" }, { type: "video", src: "assets/projects/vpn-demo.mp4", poster: "assets/projects/vpn-poster.jpg" }]
const projectMedia = {};

let currentProjectId = null;

function updateYear() {
  yearElement.textContent = new Date().getFullYear();
}

const observer = new IntersectionObserver((entries) => {
  entries.forEach((entry) => {
    if (entry.isIntersecting) {
      entry.target.style.opacity = "1";
      entry.target.style.transform = "translateY(0)";
      observer.unobserve(entry.target);
    }
  });
}, { threshold: 0.08 });

cards.forEach((card) => {
  card.style.opacity = "0";
  card.style.transform = "translateY(18px)";
  card.style.transition = "opacity 0.6s ease, transform 0.6s ease, border-color 0.25s ease";
  observer.observe(card);
});

function closeLanguageMenu() {
  languagePicker.classList.remove("open");
  languageButton.setAttribute("aria-expanded", "false");
  languageMenu.setAttribute("aria-hidden", "true");
}

function toggleLanguageMenu() {
  const isOpen = languagePicker.classList.toggle("open");
  languageButton.setAttribute("aria-expanded", String(isOpen));
  languageMenu.setAttribute("aria-hidden", String(!isOpen));
}

function renderProjectMedia(projectId) {
  if (!projectMediaGallery || !projectMediaGrid) return;

  const media = Array.isArray(projectMedia[projectId]) ? projectMedia[projectId] : [];
  projectMediaGrid.innerHTML = "";

  if (!media.length) {
    projectMediaGallery.hidden = true;
    projectMediaGallery.setAttribute("aria-hidden", "true");
    return;
  }

  media.forEach((item) => {
    const frame = document.createElement("div");
    frame.className = "project-media-item";

    if (item.type === "video") {
      const video = document.createElement("video");
      video.src = item.src;
      if (item.poster) video.poster = item.poster;
      video.controls = true;
      video.preload = "metadata";
      video.playsInline = true;
      frame.appendChild(video);
    } else {
      const image = document.createElement("img");
      image.src = item.src;
      image.alt = item.alt || "";
      image.loading = "lazy";
      frame.appendChild(image);
    }

    projectMediaGrid.appendChild(frame);
  });

  projectMediaGallery.hidden = false;
  projectMediaGallery.setAttribute("aria-hidden", "false");
}

function renderModal(projectId) {
  if (!projectId || !projectCatalog[projectId]) {
    return;
  }

  const language = document.documentElement.lang === "uk" ? "uk" : "en";
  const project = projectCatalog[projectId];

  projectModalTitle.textContent = project.icon + " " + project.name;
  projectModalText.textContent = project[language];
  renderProjectMedia(projectId);
  projectModalStatus.textContent = language === "uk"
    ? (project.status === "IN PROGRESS" ? "В ПРОЦЕСІ" : "У ПЛАНАХ")
    : project.status;

  if (project.page) {
    projectModalLink.hidden = false;
    projectModalLink.href = project.page;
    projectModalLink.removeAttribute("aria-hidden");
  } else {
    projectModalLink.hidden = true;
    projectModalLink.href = "#";
    projectModalLink.setAttribute("aria-hidden", "true");
  }
}

function openProject(projectId) {
  if (!projectCatalog[projectId]) {
    return;
  }

  currentProjectId = projectId;
  renderModal(projectId);
  projectModal.classList.add("open");
  projectModal.setAttribute("aria-hidden", "false");
  document.body.style.overflow = "hidden";
}

function closeProject() {
  currentProjectId = null;
  projectModal.classList.remove("open");
  projectModal.setAttribute("aria-hidden", "true");
  document.body.style.overflow = "";
}

document.addEventListener("click", (event) => {
  const button = event.target.closest(".project-view");

  if (!button) {
    return;
  }

  event.preventDefault();
  event.stopPropagation();
  openProject(button.dataset.project);
});

document.querySelectorAll("[data-modal-close]").forEach((element) => {
  element.addEventListener("click", closeProject);
});

function setLanguage(language) {
  const selected = translations[language] ? language : "en";

  document.documentElement.lang = selected;

  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const key = element.dataset.i18n;
    const value = translations[selected][key];

    if (value !== undefined) {
      element.innerHTML = value;
    }
  });

  currentLanguage.textContent = ({ en:"EN", uk:"UA", pl:"PL", de:"DE", es:"ES", fr:"FR", ja:"日本" })[selected] || "EN";

  languageOptions.forEach((option) => {
    option.classList.toggle("active", option.dataset.language === selected);
  });

  localStorage.setItem("flekiii-language", selected);
  updateYear();
  updateFlekiConvertDownloadStatus();

  if (currentProjectId) {
    renderModal(currentProjectId);
  }

  closeLanguageMenu();
}

languageButton.addEventListener("click", (event) => {
  event.stopPropagation();
  toggleLanguageMenu();
});

languageOptions.forEach((option) => {
  option.addEventListener("click", () => {
    setLanguage(option.dataset.language);
  });
});

document.addEventListener("click", (event) => {
  if (!languagePicker.contains(event.target)) {
    closeLanguageMenu();
  }
});

document.addEventListener("keydown", (event) => {
  if (event.key === "Escape") {
    closeLanguageMenu();

    if (projectModal.classList.contains("open")) {
      closeProject();
    }}
});


const themePicker = document.getElementById("themePicker");
const themeButton = document.getElementById("themeButton");
const themeMenu = document.getElementById("themeMenu");
const currentTheme = document.getElementById("currentTheme");
const themeOptions = document.querySelectorAll(".theme-option");
const baseThemeNames = { pink:"Rose", blue:"Ocean", purple:"Lavender", green:"Emerald", amber:"Amber", crimson:"Crimson", ice:"Ice", sunset:"Sunset", mint:"Mint", violet:"Violet", graphite:"Graphite", cherry:"Cherry", solar:"Solar" };
const themeNames = Object.fromEntries(Object.entries(baseThemeNames).flatMap(([id,name]) => [[id, name+" Dark"],[id+"-light",name+" Light"]]));
const allowedThemes = Object.keys(themeNames);

function setTheme(theme) {
  const legacy = theme === "light" ? "pink-light" : theme;
  const selected = allowedThemes.includes(legacy) ? legacy : "pink";
  document.documentElement.dataset.theme = selected;
  currentTheme.textContent = themeNames[selected];
  themeOptions.forEach((option) => option.classList.toggle("active", option.dataset.theme === selected));
  localStorage.setItem("flekiii-theme", selected);
  themeButton.setAttribute("aria-expanded", "false");
  themeMenu.setAttribute("aria-hidden", "true");
  themePicker.classList.remove("open");
}
themeButton.addEventListener("click", (event) => {
  event.stopPropagation();
  const open = themePicker.classList.toggle("open");
  themeButton.setAttribute("aria-expanded", String(open));
  themeMenu.setAttribute("aria-hidden", String(!open));
});
themeOptions.forEach((option) => option.addEventListener("click", (event) => { event.stopPropagation(); setTheme(option.dataset.theme); }));
document.addEventListener("click", (event) => {
  if (!themePicker.contains(event.target)) {
    themePicker.classList.remove("open");
    themeButton.setAttribute("aria-expanded", "false");
    themeMenu.setAttribute("aria-hidden", "true");
  }
});
setTheme(localStorage.getItem("flekiii-theme") || "pink");

const savedLanguage = localStorage.getItem("flekiii-language");
setLanguage(savedLanguage || "en");
updateYear();
loadGithubActivity();


/* Fresh Share Site implementation — no dependencies on the old modal */
(() => {
  const layer = document.getElementById("siteShareLayer");
  const openButton = document.getElementById("siteShareOpen");
  const closeButton = document.getElementById("siteShareClose");
  const backdrop = document.getElementById("siteShareBackdrop");
  const copyButton = document.getElementById("siteShareCopy");
  const status = document.getElementById("siteShareStatus");
  const viberLink = document.getElementById("siteShareViber");
  const siteUrl = "https://flekiii.github.io/";
  const shareText = "My flekiii website: " + siteUrl;

  if (!layer || !openButton) return;

  const close = () => {
    layer.classList.remove("is-visible");
    layer.setAttribute("aria-hidden", "true");
    document.body.style.overflow = "";
    openButton.focus({ preventScroll: true });
  };

  const open = () => {
    document.getElementById("siteShareTelegram").href =
      "https://t.me/share/url?url=" + encodeURIComponent(siteUrl) +
      "&text=" + encodeURIComponent("My flekiii website");
    document.getElementById("siteShareWhatsApp").href =
      "https://wa.me/?text=" + encodeURIComponent(shareText);
    document.getElementById("siteShareViber").href =
      "viber://forward?text=" + encodeURIComponent(shareText);
    layer.classList.add("is-visible");
    layer.setAttribute("aria-hidden", "false");
    document.body.style.overflow = "hidden";
    closeButton.focus({ preventScroll: true });
  };

  viberLink.addEventListener("click", async (event) => {
    event.preventDefault();
    const viberUrl = "viber://forward?text=" + encodeURIComponent(shareText);
    try {
      await navigator.clipboard.writeText(siteUrl);
      status.textContent = "Website link copied. Opening Viber…";
    } catch (error) {
      status.textContent = "Opening Viber…";
    }
    window.location.href = viberUrl;
  });

  openButton.addEventListener("click", open);
  closeButton.addEventListener("click", close);
  backdrop.addEventListener("click", close);
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && layer.classList.contains("is-visible")) close();
  });

  copyButton.addEventListener("click", async () => {
    try {
      await navigator.clipboard.writeText(siteUrl);
      status.textContent = "Link copied!";
    } catch (error) {
      const field = document.createElement("textarea");
      field.value = siteUrl;
      field.readOnly = true;
      field.style.position = "fixed";
      field.style.left = "-9999px";
      document.body.appendChild(field);
      field.select();
      const copied = document.execCommand("copy");
      field.remove();
      status.textContent = copied ? "Link copied!" : "Please copy: " + siteUrl;
    }
  });
})();
